use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::{Path,PathBuf},collections::BTreeMap,fmt::Write,process::{Command,Stdio}};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-borrowed-merge176";
const OUT:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-11-06-g2-borrowed-merge176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn walk(p:&Path)->Vec<PathBuf>{let mut v=vec![];for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){v.extend(walk(&p));}else{v.push(p);}}v.sort();v}
fn gzip(p:&Path,v:&Value){let bytes=serde_json::to_vec(v).unwrap();let tmp=p.with_extension("tmp");fs::write(&tmp,&bytes).unwrap();assert!(Command::new("gzip").args(["-n","-c"]).arg(&tmp).stdout(Stdio::from(fs::File::create(p).unwrap())).status().unwrap().success());let out=Command::new("gzip").args(["-d","-c"]).arg(p).output().unwrap();assert!(out.status.success());assert_eq!(out.stdout,bytes);fs::remove_file(tmp).unwrap();}
fn main(){let a=read(r("analysis.json"));let review=read(r("review.json"));assert_eq!(review["passed"],true);assert!(!Path::new(OUT).exists());let out=Path::new(OUT);fs::create_dir_all(out.join("artifacts")).unwrap();
 let mut sources=BTreeMap::new();for p in walk(&r("source")){let b=fs::read(&p).unwrap();let hex=b.iter().map(|b|format!("{b:02x}")).collect::<String>();let recover=hex.as_bytes().chunks_exact(2).map(|s|u8::from_str_radix(std::str::from_utf8(s).unwrap(),16).unwrap()).collect::<Vec<_>>();assert_eq!(recover,b);sources.insert(p.strip_prefix(r("source")).unwrap().display().to_string(),json!({"hex":hex,"length":b.len(),"sha256":hash(&b)}));}assert_eq!(sources.len(),177);gzip(&out.join("artifacts/source-snapshot.hex.json.gz"),&json!(sources));
 let mut receipts=BTreeMap::new();let mut add=|p:PathBuf|{let b=fs::read(&p).unwrap();let s=String::from_utf8(b.clone()).unwrap();assert_eq!(s.as_bytes(),b);receipts.insert(p.display().to_string(),json!({"utf8":s,"length":b.len(),"sha256":hash(&b)}));};
 for d in["native","consumers","runs","initial-review-timeout-prefix","host"]{for p in walk(&r(d)){if matches!(p.extension().and_then(|e|e.to_str()),Some("json"|"jsonl"|"log"|"rs"|"txt")){add(p);}}}
 for n in["setup.rs","setup.log","setup-build.log","prepare.rs","prepare.log","prepare-build.log","native.rs","native.log","native-build.log","native-plan.json","build-pins.json","consumers.rs","consumers-setup.log","consumers-finish.log","consumers.log","consumers-build.log","consumer-plan.json","consumer-pins.json","prepare-capture-source.rs","prepare-capture-source.log","prepare-capture-source-build.log","capture.rs","capture-build.log","capture-prepare.log","run.log","capture-plan.json","capture-pins.json","capture-base-pins.json","jobs.json","cases.json","identities.json","source-audit.json","probe-export.rs","driver.rs","perf_support.rs","sampling.rs","counter.rs","fixtures.json","native-flags.txt","candidate-flags.txt","review.rs","review-build.log","review.log","publish.rs","publish-build.log","design.md","protocol.md"]{if r(n).exists(){add(r(n));}}
 for j in read(r("jobs.json")).as_array().unwrap(){if let Some(p)=j["reused_from"].as_str(){for p in walk(Path::new(p)){add(p);}}}
 let receipt_count=receipts.len();gzip(&out.join("artifacts/receipts.json.gz"),&json!(receipts));
 for n in["analysis.json","review.json","symbols.json","protocol.md","design.md","review.rs","publish.rs","merge.rs"]{fs::copy(r(n),out.join("artifacts").join(n)).unwrap();}
 let mut inventory=vec![];for j in read(r("jobs.json")).as_array().unwrap().iter().filter(|j|j["panel"]=="cycles"){let p=j["data"].as_str().unwrap();let b=fs::read(p).unwrap();inventory.push(json!({"path":p,"length":b.len(),"sha256":hash(&b),"binary":j["binary"],"profile":j["name"]}));}fs::write(out.join("artifacts/raw-profile-inventory.json"),serde_json::to_vec_pretty(&inventory).unwrap()).unwrap();
 let gate=a["complete_query_gate_passed"]==true;let status=if gate{"Component gate passed; full SDK qualification pending. No adoption."}else{"Rejected. No adoption or full SDK trial from this result."};
 let mut md=format!("# Borrowed G2 bucket merge experiment\n\n**{status}** This replaces owned ordinary right-operand records with references during existing 512-entry G2 bucket merges. Arithmetic, bucket geometry, grouping, pools and keys stay the same. Production and accepted full-proof timings are unchanged.\n\nRyzen 9950X, 16 physical cores / 32 logical CPUs. Fresh OFF/ON and inherited optimized FROZEN use identical complete-query drivers and verified O/native/fat-LTO/one-codegen-unit flags. Each caller primes three times, times 17 queries and checks once more. The table reports medians of 15 process medians; paired ratios need not equal ratios of those displayed times. All allocation/drop, reset copies, grouping, merges and normalization are timed; parsing and pool creation are outside.\n\n|Query / workers|FROZEN ms|OFF ms|ON ms|ON/OFF [bounds]|Wins/15|OFF/ON max RSS MiB|\n|---|---:|---:|---:|---|---:|---:|\n");
 for(name,c)in a["cases"].as_object().unwrap(){let q=&c["ON_comparisons"]["OFF"];writeln!(md,"|{name}|{:.6}|{:.6}|{:.6}|{:.6} [{:.6}, {:.6}]|{}|{:.2}/{:.2}|",c["FROZEN_ns"]["median"].as_f64().unwrap()/1e6,c["OFF_ns"]["median"].as_f64().unwrap()/1e6,c["ON_ns"]["median"].as_f64().unwrap()/1e6,q["median"].as_f64().unwrap(),q["lower"].as_f64().unwrap(),q["upper"].as_f64().unwrap(),q["wins"],c["OFF_max_RSS_MiB"].as_f64().unwrap(),c["ON_max_RSS_MiB"].as_f64().unwrap()).unwrap();}
 let ag=&a["two_shape_32_aggregate"]["OFF"];writeln!(md,"\nBoth B shapes at 32 workers aggregate to {:.6} [{:.6}, {:.6}], {}/15 wins. Fresh-OFF nonregression: {}; primary/aggregate gain: {}; diagnostic qualification: {}. OFF/FROZEN 3% calibration: {}. The frozen/fresh discrepancy was unresolved before this experiment, so calibration is descriptive and component gates use fresh OFF as declared in the protocol. No component or control result establishes an accepted full-proof gain.\n",ag["median"].as_f64().unwrap(),ag["lower"].as_f64().unwrap(),ag["upper"].as_f64().unwrap(),ag["wins"],a["nonregression_passed"],a["gain_passed"],a["diagnostics_qualified"],a["calibration_passed"]).unwrap();
 md.push_str("Native layout checks confirm 128-byte G2 points, 136-byte owned records and 16-byte borrowed records: 61,440 fewer requested pair-vector bytes per full 512-entry job. This is a local temporary-payload reduction, not proof-wide peak-RAM savings. The existing forecast remains conservative for requested heap capacity; stack headers, allocator retention and process RSS are separate. Unsupported/disabled dispatch returns before mutation and retains the existing fallback.\n\nFull unfiltered suites pass 125 OFF and 129 ON tests. Four new tests cover actual record layouts, independent generator-sum oracles for ordinary/identity/doubling/opposite points and SIMD tails, typed disabled fallback without mutation, repeated calls, immutable right inputs, and public merge chunk boundaries at 1/4/16/32 workers with 512 KiB stacks. Test-only dispatch counts prove the path executes; timing binaries have no dispatch counters and keep the inherited API metadata at zero. Existing field qualification is inherited, not rerun. Both libraries and all transitive native dependencies are frozen coherently.\n\nThe 177-file snapshot preserves 172 of 176 originals byte-exact; all originals recover by reversing narrow dispatch/visibility/export edits and suffixes. All original field and arithmetic bodies are unchanged. Initial source/compile and qualification receipts are retained. No successful recording is repeated. Seven exact frozen preflight receipts are reused, with 341 new caller processes: 348 qualified rows, 9,168 query invocations including 35 reused. These are component queries on fixed fixtures, not serialized proofs or distinct witnesses.\n\nAll 315 latency callers finish before six PMU panels and six separate cycles profiles. Diagnostics use FIFO-controlled 200-query intervals, fixed 16M cycles:u sampling, checked actual PID/worker TID/CPU/executable MMAP and zero loss. Profiles and generic cache misses do not identify a causal memory level or critical path. Independent review reconstructs performance statistics/gates, source recovery, receipts, final flags, RSS and exact profile ownership/period/CPU mapping. Raw PMU parsing and symbol qualification remain in the capture helper; review does not claim a second PMU parser.\n\nAccepted local full-proof results and supplied M5 references are inherited:\n\n|Shape|Accepted ms|M5 CPU ms|M5 Metal ms|CPU10x target ms|\n|---|---:|---:|---:|---:|\n");
 for(shape,t,cpu,metal)in[("1x2",7.928660,37.,24.),("2x2",11.151932,59.,30.),("4x2",16.086386,109.,48.),("8x2",24.179453,189.,74.),("12x2",33.884455,284.,101.),("16x2",40.077381,335.,124.),("24x2",65.850777,528.,176.),("merge24",65.060937,507.,175.)]{writeln!(md,"|{shape}|{t:.6}|{cpu:.0}|{metal:.0}|{:.1}|",cpu/10.).unwrap();}
 md.push_str("\nMerge54 stays 161.883899 ms without a supplied M5 reference. SDK SHA-256 remains `6d83f1d6fda6f16576cb351b81789e8d26a6177cc0f26f169a3dc98448c0e661`; proof ledger stays 30,708. All-eight CPU10x remains active and unmet, 0/8. No new SDK/Gnark, AWS/Aeglos, phone, pressure/swap, minimum-RAM or concurrent-throughput result is claimed.\n\n[Analysis](artifacts/analysis.json), [review](artifacts/review.json), [protocol](artifacts/protocol.md), [source snapshot](artifacts/source-snapshot.hex.json.gz), [receipts and helpers](artifacts/receipts.json.gz), [raw profile inventory](artifacts/raw-profile-inventory.json), [checksums](SHA256SUMS). Source hex and UTF-8 receipt archives round-trip exact bytes, lengths and hashes. Runtime point/scalar fixtures, private keys/witnesses, executables, libraries and raw perf.data stay local with hashes. Reproduction requires pinned toolchain/dependencies and private fixtures. Private root: `/home/ubuntu/src/zopro-perf-work/g2-borrowed-merge176`.\n");
 fs::write(out.join("README.md"),md).unwrap();let mut sums=String::new();let files=walk(out);for p in &files{writeln!(sums,"{}  {}",hash(&fs::read(p).unwrap()),p.strip_prefix(out).unwrap().display()).unwrap();}fs::write(out.join("SHA256SUMS"),sums).unwrap();println!("Published {} files, 177 source members, {receipt_count} exact UTF8 receipt members; archive roundtrips passed; adopted=false",files.len()+1);
}
